#!/usr/bin/env python3
"""Generate resources.h for Hot Fuzz.

Produces two 256-entry LUTs that map control values to Braids SVF `frequency_`
indices, giving an octave-linear sweep from 300 Hz to 2000 Hz:

  - manual_freq_LUT[256]: indexed by (Main pot >> 4), 0..255
  - env_freq_LUT[256]:    indexed by (envelope >> 4), 0..255

The Braids SVF resolves `frequency_` to an `f` coefficient via
`Interpolate824(lut_svf_cutoff, frequency_ << 17)`.  With 8.24 interpolation
the effective LUT index is `frequency_ >> 7` (0..256).  We invert that
relationship by searching the cutoff table for the `f` that yields a given
cutoff, then back-mapping to `frequency_`.

The script is deterministic: the same inputs always produce the same output,
so checking resources.h into version control is safe.

Run:
    python3 tools/gen_luts.py > resources.h
"""

import math
import sys
import textwrap

# --- Braids lut_svf_cutoff (257 entries) ------------------------------------
# Vendored from releases/10_twists/src/braids/resources.cc so the generator
# is self-contained.  Only the first 129 entries vary; the rest saturate at
# 25078 (Nyquist clamp).
LUT_SVF_CUTOFF = [
    17, 18, 19, 20, 22, 23, 24, 26, 27, 29, 31, 33, 35, 37, 39, 41,
    44, 46, 49, 52, 55, 58, 62, 66, 70, 74, 78, 83, 88, 93, 99, 105,
    111, 117, 124, 132, 140, 148, 157, 166, 176, 187, 198, 210, 222, 235, 249, 264,
    280, 297, 314, 333, 353, 374, 396, 420, 445, 471, 499, 529, 561, 594, 629, 667,
    706, 748, 793, 840, 890, 943, 999, 1059, 1122, 1188, 1259, 1334, 1413, 1497, 1586, 1681,
    1781, 1886, 1999, 2117, 2243, 2377, 2518, 2668, 2826, 2994, 3172, 3361, 3560, 3772, 3996, 4233,
    4485, 4751, 5033, 5332, 5648, 5983, 6337, 6713, 7111, 7532, 7978, 8449, 8949, 9477, 10037, 10628,
    11254, 11916, 12616, 13356, 14138, 14964, 15837, 16758, 17730, 18756, 19837, 20975, 22174, 23435, 24761,
] + [25078] * 130
assert len(LUT_SVF_CUTOFF) == 257

# f coefficient (Q15) that the SVF uses at index i.
# fc(Hz) = f * fs / (2*pi)  (approximation valid for fc << fs/2)
FS = 48000.0


def index_to_hz(idx):
    """Convert a fractional LUT index (0..256) to cutoff Hz."""
    i0 = int(idx)
    i1 = min(i0 + 1, 256)
    frac = idx - i0
    f_q15 = LUT_SVF_CUTOFF[i0] + (LUT_SVF_CUTOFF[i1] - LUT_SVF_CUTOFF[i0]) * frac
    f = f_q15 / 32768.0
    # Invert f = 2*sin(pi*fc/fs):  fc = (fs/(2*pi)) * asin(f/2)
    # For small f the linear approx fc = f*fs/(2*pi) is accurate enough;
    # for larger f use the arcsin form to stay correct near Nyquist.
    arg = f / 2.0
    arg = min(1.0, max(-1.0, arg))
    return FS * math.asin(arg) / math.pi


def hz_to_index(hz):
    """Binary-search the cutoff table for the index whose fc matches `hz`.

    Returns a float index 0..256.  frequency_ = round(index * 128).
    """
    lo, hi = 0.0, 256.0
    for _ in range(48):  # ~48 iterations gives sub-sample precision
        mid = (lo + hi) * 0.5
        fc = index_to_hz(mid)
        if fc < hz:
            lo = mid
        else:
            hi = mid
    return (lo + hi) * 0.5


def build_lut(hz_min, hz_max, n):
    """Octave-linear LUT: equal steps in log2(Hz) map to entries 0..n-1."""
    if hz_min <= 0:
        hz_min = 1.0
    log_min = math.log2(hz_min)
    log_max = math.log2(hz_max)
    out = []
    for i in range(n):
        t = i / (n - 1)
        hz = 2.0 ** (log_min + t * (log_max - log_min))
        idx = hz_to_index(hz)
        # frequency_ = idx * 128  (so that frequency_ << 17 >> 24 == idx)
        out.append(int(round(idx * 128)))
    return out


def emit(name, values, per_line=8):
    print(f"static const uint16_t {name}[{len(values)}] = {{")
    for i in range(0, len(values), per_line):
        chunk = values[i:i + per_line]
        print("    " + ", ".join(f"{v:5d}" for v in chunk) + ",")
    print("};")
    print()


def main():
    manual = build_lut(300.0, 2000.0, 256)
    env    = build_lut(300.0, 2000.0, 256)

    header = f"""\
// resources.h — Hot Fuzz control-rate LUTs, generated by tools/gen_luts.py.
//
// Two 256-entry octave-linear tables mapping control values to Braids SVF
// `frequency_` indices (the value passed to Svf::set_frequency).  The SVF
// resolves that to an `f` coefficient via Interpolate824(lut_svf_cutoff,
// frequency_ << 17), so an index in 0..32760 covers the full stable range.
//
//  - manual_freq_LUT: indexed by (Main pot >> 4), sweeps 300 Hz .. 2 kHz.
//  - env_freq_LUT:     indexed by (envelope >> 4), same sweep for auto-wah.
//
// Regenerate with:  python3 tools/gen_luts.py > resources.h

#ifndef HOT_FUZZ_RESOURCES_H
#define HOT_FUZZ_RESOURCES_H

#include <stdint.h>

namespace hotfuzz {{
"""
    sys.stdout.write(header)
    emit("manual_freq_LUT", manual)
    emit("env_freq_LUT", env)
    sys.stdout.write("}  // namespace hotfuzz\n\n#endif  // HOT_FUZZ_RESOURCES_H\n")


if __name__ == "__main__":
    main()